'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)], esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='leseliebe-v1';const day=(d=new Date())=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;const uid=()=>crypto.randomUUID?crypto.randomUUID():'id-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2);
const defaults=()=>({version:1,roomWorld:'park',roomLight:'warm',roomMotion:true,name:'Jenna',coins:0,earned:0,books:[],logs:[],owned:['chair','plant'],placed:[{id:'chair',x:70,y:82},{id:'plant',x:24,y:79}],claims:[],challenges:[],theme:'forest',sound:'off',minutes:30,volume:35});
let state;try{state={...defaults(),...JSON.parse(localStorage.getItem(KEY)||'{}')}}catch{state=defaults()}
let page='room',filter='Alle',editing=false,selected=null,session=null,interval=null,wake=null,audio=null,audioNodes=[],master=null,scanStream=null,scanInterval=null,searchHits=[],discoverHits=[],journalRating=0;
function save(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch{toast('Speichern nicht möglich. Bitte eine Datensicherung exportieren.')}$('#coins').textContent=state.coins;$('.avatar').textContent=state.name.slice(0,1).toUpperCase()}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>$('#toast').classList.remove('show'),4000)}
function modal(html){$('#modalBody').innerHTML=html;labelFields($('#modalBody'));$('#modal').showModal()}
function closeModal(){stopScan();$('#modal').close()}
$('#modal').addEventListener('close',stopScan);$('#modal').addEventListener('cancel',stopScan);
function menu(v){$('#menu').hidden=!v;$('#shade').hidden=!v;$('#menuBtn').setAttribute('aria-expanded',v)}
$('#menuBtn').onclick=()=>menu(true);$('#closeMenu').onclick=()=>menu(false);$('#shade').onclick=()=>menu(false);$('#profileBtn').onclick=()=>location.hash='settings';$('nav').onclick=e=>{if(e.target.closest('a'))menu(false)};
window.addEventListener('hashchange',render);window.addEventListener('keydown',e=>{if(e.key==='Escape')menu(false)});
const sum=(key,date)=>state.logs.filter(l=>!date||l.day===date).reduce((a,l)=>a+(Number(l[key])||0),0);
function streak(){let n=0,d=new Date();if(!state.logs.some(l=>l.day===day(d)))d.setDate(d.getDate()-1);for(let i=0;i<2000;i++){if(!state.logs.some(l=>l.day===day(d)))break;n++;d.setDate(d.getDate()-1)}return n}
const items=[{id:'chair',name:'Lieblingssessel',price:0,desc:'Ein weicher Platz für große Geschichten.'},{id:'plant',name:'Grüner Mitbewohner',price:0,desc:'Wächst auch ohne grünen Daumen.'},{id:'lamp',name:'Warmes Leselicht',price:45,desc:'Ein goldener Lichtschein für lange Kapitel.'},{id:'rug',name:'Wolkenteppich',price:60,desc:'Für warme Füße und noch wärmere Geschichten.'},{id:'table',name:'Kleiner Beistelltisch',price:50,desc:'Platz für Tee. Und den nächsten Plot-Twist.'},{id:'cat',name:'Schlafende Katze',price:95,desc:'Schnurrt in Gedanken neben dir.'},{id:'books',name:'Noch ein Bücherstapel',price:35,desc:'Zu viele Bücher? Unmöglich.'},{id:'candles',name:'Kerzenschein',price:40,desc:'Ein bisschen Magie für deinen Rückzugsort.'},{id:'flowers',name:'Wiesenblumen',price:65,desc:'Ein kleiner Strauß voller Leichtigkeit.'},{id:'moon',name:'Mondlampe',price:120,desc:'Das Universum passt auf deinen Tisch.'},{id:'shelf',name:'Lieblingsregal',price:150,desc:'Mehr Raum für deine nächsten Welten.'},{id:'tea',name:'Eine Tasse Auszeit',price:25,desc:'Das Glück steckt in den kleinen Pausen.'}];
